const j = $json.output || $json;
const now = new Date(Date.now() + 7 * 3600 * 1000);
const p2 = n => String(n).padStart(2, '0');
const tgl = `${now.getUTCFullYear()}-${p2(now.getUTCMonth() + 1)}-${p2(now.getUTCDate())}`;
const jam = `${p2(now.getUTCHours())}:${p2(now.getUTCMinutes())}`;
const judul = (j.judul || 'Tanpa Judul').replace(/[\\/:*?"<>|]/g, '-').trim();

const tagList = (j.tags || [])
  .map(t => String(t).replace(/^#/, '').trim().replace(/\s+/g, '-'))
  .filter(Boolean);
const tagYaml = tagList.length ? `tags:\n${tagList.map(t => `  - ${t}`).join('\n')}\n` : '';

const lamp = j.lampiran ? `lampiran: "[[${j.lampiran}]]"\n` : '';
const media = j.lampiran ? `![[${j.lampiran}]]\n\n` : '';
const body = j.transkrip
  ? `## Transkrip\n\n${j.transkrip}\n\n## Rangkuman\n\n${j.isi}`
  : j.isi;
const isi = `---\ntitle: ${judul}\ndate: ${tgl} ${jam}\n${tagYaml}${lamp}---\n\n# ${judul}\n\n${media}${body}\n`;

return [{
  json: { filename: `/vault/2nd-brain/notes/${tgl}_${judul}.md`, judul },
  binary: {
    data: {
      data: Buffer.from(isi, 'utf8').toString('base64'),
      mimeType: 'text/markdown',
      fileName: `${tgl}_${judul}.md`
    }
  }
}];

